<?php
function lineEditorRow(array $line,int $index): void {
    $text=static fn($key,$default='')=>isset($line[$key])&&is_scalar($line[$key])?(string)$line[$key]:$default;
    ?><fieldset class="line-editor-row" data-line-row><legend>Ligne <span data-line-number><?=$index+1?></span></legend><div class="line-editor-fields"><label class="line-designation">Désignation *<input name="lines[<?=$index?>][designation]" value="<?=e($text('designation'))?>" maxlength="190" required></label><label>Quantité *<input name="lines[<?=$index?>][quantity]" data-line-field="quantity" type="number" min="0.001" max="999999.999" step="0.001" value="<?=e($text('quantity','1.000'))?>" required></label><label>Unité<select name="lines[<?=$index?>][unit]"><?php foreach(LINE_UNITS as $unit):?><option <?=($text('unit','u')===$unit)?'selected':''?>><?=e($unit)?></option><?php endforeach?></select></label><label>P.U. HT · DH *<input name="lines[<?=$index?>][unit_price]" data-line-field="unit_price" type="number" min="0" max="9999999.99" step="0.01" value="<?=e($text('unit_price','0.00'))?>" required></label><label>Remise · % *<input name="lines[<?=$index?>][discount_rate]" data-line-field="discount_rate" type="number" min="0" max="100" step="0.01" value="<?=e($text('discount_rate','0.00'))?>" required></label><label>TVA · % *<input name="lines[<?=$index?>][tax_rate]" data-line-field="tax_rate" type="number" min="0" max="100" step="0.01" value="<?=e($text('tax_rate','0.00'))?>" required></label></div><div class="line-editor-footer"><span>HT net : <output data-line-net>—</output> · TTC : <output data-line-total>—</output></span><button type="button" class="text-button" data-remove-line>Retirer cette ligne</button></div></fieldset><?php
}
if($_SERVER['REQUEST_METHOD']==='POST'&&in_array($_POST['action']??'',['order_save','quote_draft_save'],true)&&isset($_POST['lines'])&&is_array($_POST['lines']))$editorLines=array_slice(array_values($_POST['lines']),0,MAX_ORDER_LINES);
else $editorLines=$id?orderLineItems($order):[['designation'=>'','quantity'=>'1.000','unit'=>'u','unit_price'=>'0.00','discount_rate'=>'0.00','tax_rate'=>$meta['default_tax_rate']??'0.00']];
?><div id="line-editor" data-default-tax="<?=e($meta['default_tax_rate']??'0.00')?>"><div class="line-editor-list" data-line-list><?php foreach($editorLines as $lineIndex=>$line)lineEditorRow(is_array($line)?$line:[],$lineIndex);?></div><div class="export-actions"><button type="button" class="btn secondary" data-add-line>＋ Ajouter une ligne</button><span class="small muted">1 à 50 lignes · Remise par ligne · TVA après remise</span></div><p id="line-errors" role="alert" class="overdue"></p><div class="finance-summary standalone" aria-live="polite"><div><span>HT avant remise</span><strong data-total-gross>—</strong></div><div><span>Remises</span><strong data-total-discount>—</strong></div><div><span>HT net</span><strong data-total-net>—</strong></div><div><span>TVA</span><strong data-total-tax>—</strong></div></div><div class="total-preview"><span>Total TTC</span><output id="order-total" data-total-gross-total>—</output><small>Arrondi au centime par ligne · somme des lignes</small></div></div>
